func (h *ExecuteHealHandler) resolvePKColumnAndType(targetTable string, ref *servicerecon.MasterBindingRef) (string, string) {
	pkCol := ""
	pkType := "string"
	if ref != nil && strings.TrimSpace(ref.TransformSpec) != "" {
		var spec struct {
			PK string `json:"pk"`
		}
		if err := json.Unmarshal([]byte(ref.TransformSpec), &spec); err == nil {
			cand := strings.TrimSpace(spec.PK)
			if cand != "" && cand != "_gpay_id" {
				pkCol = cand
			}
		}
	}
	entry := h.resolveTargetTableConfig(targetTable)
	if entry == nil && ref != nil && ref.ShadowTable != "" {
		entry = h.resolveTargetTableConfig(ref.ShadowRel())
		if entry == nil {
			entry = h.resolveTargetTableConfig(ref.ShadowTable)
		}
	}
	if entry != nil {
		if pkCol == "" && entry.PrimaryKeyField != "" {
			pkCol = entry.PrimaryKeyField
		}
		if entry.PrimaryKeyType != "" {
			pkType = strings.ToLower(strings.TrimSpace(entry.PrimaryKeyType))
		}
	}
	if pkCol == "" {
		pkCol = "_id"
	}
	return pkCol, pkType
}

